// ---- PATCH /v1/me ----

/** Phriend is for people 18 and over (the age gate). */
export const MIN_AGE = 18;
export const MAX_AGE = 120;

/** Whole years between a YYYY-MM-DD birthdate and a YYYY-MM-DD day. */
export function ageOn(birthdate: string, day: string): number {
  const [by, bm, bd] = birthdate.split("-").map(Number) as [number, number, number];
  const [y, m, d] = day.split("-").map(Number) as [number, number, number];
  return y - by - (m < bm || (m === bm && d < bd) ? 1 : 0);
}

/** Why a birthdate is refused (user-ready), or null. `today` is the Manila calendar day. */
export function birthdateProblem(birthdate: string, today: string = manilaToday()): string | null {
  if (!isManilaDay(birthdate) || Number.isNaN(fromManila(birthdate).getTime())) return "Enter a valid date.";
  if (birthdate > today) return "Enter a date in the past.";
  const age = ageOn(birthdate, today);
  if (age > MAX_AGE) return "Enter a valid date.";
  if (age < MIN_AGE) return `Phriend is for people ${MIN_AGE} and over.`;
  return null;
}

